(()=>{
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
let lang='es';try{lang=localStorage.getItem('patio-language')==='en'?'en':'es'}catch{}
function translate(next){lang=next;document.documentElement.lang=lang;$$('[data-es][data-en]').forEach(el=>{el.innerHTML=el.dataset[lang]});$('.lang').textContent=lang==='es'?'EN':'ES';$('.lang').setAttribute('aria-label',lang==='es'?'Switch to English':'Cambiar a español');try{localStorage.setItem('patio-language',lang)}catch{}}
translate(lang);$('.lang').addEventListener('click',()=>translate(lang==='es'?'en':'es'));
$('.menu-toggle').addEventListener('click',e=>{const open=$('.header').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.textContent=open?'×':'☰'});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.header').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').textContent='☰'}});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduced){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el));
const visual=$('.hero-visual');if(visual&&CSS.supports('animation-timeline: scroll()')){visual.animate([{clipPath:'inset(0% 0% 0% 0% round 0px)'},{clipPath:'inset(3% 8% 3% 8% round 180px 180px 0px 0px)'}],{fill:'both',timeline:new ScrollTimeline({source:document.documentElement}),rangeStart:'0px',rangeEnd:'750px'});}}
const hero=$('#hero-video'),heroButton=$('#hero-play');if(hero){heroButton.addEventListener('click',async()=>{if(hero.paused){try{await hero.play();$('.hero-visual').classList.add('playing');heroButton.textContent='Ⅱ';heroButton.setAttribute('aria-label','Pausar vídeo del patio')}catch{heroButton.textContent='▶'}}else{hero.pause();heroButton.textContent='▶';heroButton.setAttribute('aria-label','Reproducir vídeo del patio')}});const watcher=new IntersectionObserver(([entry])=>{if(!entry.isIntersecting&&!hero.paused){hero.pause();heroButton.textContent='▶'}},{threshold:.1});watcher.observe(hero);}
const dialog=$('#video-dialog'),player=dialog.querySelector('video');$$('[data-video]').forEach(button=>button.addEventListener('click',()=>{player.src=`assets/videos/${button.dataset.video}.mp4`;player.muted=true;$('#video-label').textContent=button.dataset.title;$('#video-source').href=button.dataset.post;dialog.showModal();document.body.style.overflow='hidden';player.play().catch(()=>{});}));function close(){dialog.close()}$('.close-video').addEventListener('click',close);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});dialog.addEventListener('close',()=>{player.pause();player.removeAttribute('src');player.load();document.body.style.overflow=''});
const form=$('#booking-form');if(form){const date=form.elements.date;const now=new Date();date.min=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const d=new Date(data.get('date')+'T12:00:00').toLocaleDateString(lang==='es'?'es-ES':'en-GB');const service=data.get('service');const message=lang==='es'?`Hola, nos gustaría reservar para ${data.get('guests')} personas el ${d}, para ${service}. ¿Tenéis disponibilidad?`:`Hello, we would like to book a table for ${data.get('guests')} guests on ${d} for ${service==='comida'?'lunch':'dinner'}. Is there availability?`;window.open('https://wa.me/34633755238?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');});}
})();
